-- Photo Mode: looks, weather over time, time-lapse, seasons and sun placement, the pure part (no api calls).
-- Shared by gui/pm_weather.lua and the offline tests (tests/square_photo_mode/test_looks.lua). Plain Lua, pre-5.3.
-- Design and in-game checks: plans/square_photo_mode/LOOKS.md.
--
-- Looks are environment files shipped by this mod, one per base climate and sky + haze + water combination
-- (content/environments/sqpm_<climate>_<sky>_<haze>_<water>.env.lua, GENERATED by tools/gen_photo_looks.py from
-- the base climate's env file). They are switched to for rendering only (api.gui.rendering.setEnvironment); the
-- game's own environment ResName (api.gui.game.getEnvironment) never changes, so nothing reaches the savegame. A
-- switch resets the live atmosphere values (clouds, day, sun rotation) to the file's: the live values are carried
-- over (LIVE).

local P = {}

local atan2 = math.atan2 or function(y, x) return math.atan(y, x) end
P.atan2 = atan2

local function finite(v)
	return type(v) == "number" and v == v and v ~= math.huge and v ~= -math.huge
end

local function clamp(v, lo, hi)
	if v ~= v then return lo end
	if v < lo then return lo end
	if v > hi then return hi end
	return v
end

local function wrapAngle(a)
	if not finite(a) then return 0 end
	local r = math.fmod(a + math.pi, 2 * math.pi)
	if r <= 0 then r = r + 2 * math.pi end
	return r - math.pi
end
P.wrapAngle = wrapAngle

---------------------------------------------------------------------------
-- Climates and looks

P.MOD_ID = "square_photo_mode"
P.ENV_PREFIX = "square_photo_mode::/environments/sqpm_"
-- The env files' names start with this (gen_photo_looks.py): how a rendering environment is recognised as ours.
P.NAME_PREFIX = "Photo Mode look:"

-- The base climates: their environment ResName (api.gui.game.getEnvironment, probe T7) and light.latitude
-- (radians, from the env files).
P.CLIMATES = {
	dry = { res = "::/climates/dry/dry.env", lat = 0.61957848072052 },
	temperate = { res = "::/climates/temperate/temperate.env", lat = 0.70684361457825 },
	subarctic = { res = "::/climates/subarctic/subarctic.env", lat = 0.87962859869003 },
	tropical = { res = "::/climates/tropical/tropical.env", lat = 0.41537535190582 },
}
P.CLIMATE_ORDER = { "dry", "temperate", "subarctic", "tropical" }

-- Looks come in three layers (round 11: sky + water; round 12: haze split off the sky; LOOKS.md "Layers", "Round 12"):
-- a sky look (the sun, moon, Rayleigh and ozone fields of the env file's `atmosphere`, and its `light` block), a
-- haze look (every mie field and the aerial perspective fogScaleLow / High) and a water look (its `water` block). An
-- env file is switched as a whole, so there is one file per combination (sqpm_<climate>_<sky>_<haze>_<water>.env.lua,
-- ORIG for a layer left as the climate's own; ORIG x3 is the climate itself). The same keys and order as
-- gen_photo_looks.py SKY / HAZE / WATER (test_looks.lua checks every file). Keys are unique across the layers.
P.ORIG = "orig"
P.LAYERS = { "sky", "haze", "water" }
-- Round 15: four more skies, one more haze and water (LOOKS.md "Round 15"; 4 x (9 x 6 x 5 - 1) = 1076 files).
P.SKY_ORDER = { "soft_light", "dramatic", "storybook", "moonlit_night", "golden_glow", "cold_blue", "vintage",
	"neon_dusk" }
P.HAZE_ORDER = { "crisp_clear", "hazy_morning", "misty_valley", "soft_background", "dust_storm" }
P.WATER_ORDER = { "mirror", "clear", "wild", "turquoise" }
P.SKY, P.HAZE, P.WATER = {}, {}, {}
for i, k in ipairs(P.SKY_ORDER) do P.SKY[k] = i end
for i, k in ipairs(P.HAZE_ORDER) do P.HAZE[k] = i end
for i, k in ipairs(P.WATER_ORDER) do P.WATER[k] = i end
P.ORDER = { sky = P.SKY_ORDER, haze = P.HAZE_ORDER, water = P.WATER_ORDER }
P.SET = { sky = P.SKY, haze = P.HAZE, water = P.WATER }

-- Round 16 (user: "Are there any other look styles we could leverage?"): whole looks, the base game's own environment
-- files switched to as they are, so they cost no file of ours. They sit in the Sky menu after the sky looks and
-- bring their own haze and water, so they don't mix: picking a haze or water look ends one (setLayer in
-- gui/pm_weather.lua). "legacy": the base game's older atmosphere, `<climate>_old.env` in every base climate folder
-- (listed by environmentRep as "(Legacy)", isToolEnvironment true; findings environment.md): a 10 km height offset,
-- Rayleigh spread 100 km high and weaker, three times the aerial perspective, brighter exposure (x1.7), a single
-- contrast value. The ResName is inferred from the base climates' own (`::/climates/<c>/<c>.env`).
P.WHOLE_ORDER = { "legacy" }
P.WHOLE = { legacy = function(climate) return "::/climates/" .. climate .. "/" .. climate .. "_old.env" end }
-- The Sky menu (the window's dropdown and its < / > arrows): the sky looks, then the whole looks.
P.MENU = { sky = {}, haze = P.HAZE_ORDER, water = P.WATER_ORDER }
for __, k in ipairs(P.SKY_ORDER) do P.MENU.sky[#P.MENU.sky + 1] = k end
for __, k in ipairs(P.WHOLE_ORDER) do P.MENU.sky[#P.MENU.sky + 1] = k end
P.MENU_SET = { sky = {}, haze = P.HAZE, water = P.WATER }
for i, k in ipairs(P.MENU.sky) do P.MENU_SET.sky[k] = i end

--- True for a whole look key ("legacy").
function P.isWhole(k)
	return type(k) == "string" and P.WHOLE[k] ~= nil
end

--- A layer's key normalised: nil, ORIG or an unknown key -> nil (the climate's own).
local function layerKey(set, k)
	if type(k) == "string" and set[k] ~= nil then return k end
	return nil
end

--- The look's key (the file stem after the climate: "<sky>_<haze>_<water>", ORIG for a layer left alone), nil
--- when all three layers are the climate's own. Unknown keys count as the climate's own.
function P.lookKey(sky, haze, water)
	if P.isWhole(sky) then return sky end -- round 16: a whole look brings its own haze and water
	sky, haze, water = layerKey(P.SKY, sky), layerKey(P.HAZE, haze), layerKey(P.WATER, water)
	if sky == nil and haze == nil and water == nil then return nil end
	return (sky or P.ORIG) .. "_" .. (haze or P.ORIG) .. "_" .. (water or P.ORIG)
end

--- The ResName of the sky + haze + water look for `climate`, nil when all three are the climate's own.
function P.lookResName(climate, sky, haze, water)
	local key = P.lookKey(sky, haze, water)
	if key == nil then return nil end
	if P.isWhole(key) then
		if P.CLIMATES[climate or ""] == nil then return nil end
		return P.WHOLE[key](climate)
	end
	return P.ENV_PREFIX .. climate .. "_" .. key .. ".env"
end

--- climate, sky, haze, water (nil = the climate's own) of one of our look ResNames, else nil. Every combination
--- is compared (9 x 6 x 5 strings for the matching climate at most), no pattern guessing at the underscores inside
--- keys.
function P.parseOurs(resName)
	if type(resName) ~= "string" then return nil end
	local rest = resName:match("^square_photo_mode::/environments/sqpm_([a-z_]+)%.env$")
	if rest == nil then return nil end
	for __, c in ipairs(P.CLIMATE_ORDER) do
		local key = rest:match("^" .. c .. "_([a-z_]+)$")
		if key ~= nil then
			for i = 0, #P.SKY_ORDER do
				local s = P.SKY_ORDER[i]
				for j = 0, #P.HAZE_ORDER do
					local h = P.HAZE_ORDER[j]
					for k = 0, #P.WATER_ORDER do
						local w = P.WATER_ORDER[k]
						if (s or h or w) ~= nil and key == P.lookKey(s, h, w) then return c, s, h, w end
					end
				end
			end
		end
	end
	return nil
end

--- The `<` / `>` arrows beside a layer's dropdown (round 15): the key `dir` (-1 or +1) steps away from `current`
--- in that layer's list, "Original" (nil) first, wrapping round at both ends. nil / ORIG / an unknown key count as
--- Original; an unknown layer gives nil.
function P.stepLook(layer, current, dir)
	local order = P.MENU[layer] -- round 16: the Sky menu ends with the whole looks
	if order == nil then return nil end
	local n = #order + 1 -- Original + the looks
	local i = P.MENU_SET[layer][current or ""] or 0 -- 0 = Original
	local step = (dir == -1) and -1 or 1
	local j = (i + step) % n
	if j < 0 then j = j + n end
	return order[j] -- order[0] is nil: Original
end

--- True when a rendering environment's name is one of our looks' (round 16: or a base "(Legacy)" environment's, the
--- Legacy whole look: base `name = "Dry (Legacy)"`, not translated; a game that uses one as its own climate is
--- switched back to that same ResName, which changes nothing).
function P.isOurName(name)
	if type(name) ~= "string" then return false end
	return name:sub(1, #P.NAME_PREFIX) == P.NAME_PREFIX or name:sub(-#P.LEGACY_SUFFIX) == P.LEGACY_SUFFIX
end
P.LEGACY_SUFFIX = " (Legacy)"

-- Words in a mod climate's or campaign map's environment ResName that tell its base climate (lower case, plain
-- find). Checked in this order; anything else gets no looks (LOOKS.md "Unknown climates").
P.KEYWORDS = {
	{ "subarctic", "subarctic" }, { "arctic", "subarctic" }, { "nordic", "subarctic" }, { "norway", "subarctic" },
	{ "tropic", "tropical" },
	{ "desert", "dry" }, { "arid", "dry" }, { "dry", "dry" },
	{ "temperate", "temperate" },
}

--- The base climate of the game's environment ResName: climate key and how it was found ("base", "ours",
--- "keyword"), or nil for an unknown (mod or campaign) climate.
function P.climateOf(resName)
	if type(resName) ~= "string" or resName == "" then return nil end
	for __, c in ipairs(P.CLIMATE_ORDER) do
		if P.CLIMATES[c].res == resName then return c, "base" end
	end
	local own = P.parseOurs(resName)
	if own ~= nil then return own, "ours" end
	local low = resName:lower()
	for __, kw in ipairs(P.KEYWORDS) do
		if low:find(kw[1], 1, true) then return kw[2], "keyword" end
	end
	return nil
end

--- What to switch back to: the game's ResName, unless that is one of ours (never set by us; a guard), then the
--- base climate's.
function P.originalResName(gameResName, climate)
	if type(gameResName) == "string" and gameResName ~= "" and P.parseOurs(gameResName) == nil then
		return gameResName
	end
	local c = P.CLIMATES[climate or ""]
	return c and c.res or nil
end

--- What the game start does about looks: the rendering environment is still one of ours (the GUI state outlived
--- a load) or the save's marker says a look was on: { to = ResName } to switch back to; else nil.
function P.startPlan(markerLook, renderName, gameResName)
	local ours = P.isOurName(renderName)
	if not ours and markerLook == nil then return nil end
	local c = P.climateOf(gameResName)
	local to = P.originalResName(gameResName, c)
	if to == nil then return nil end
	if not ours then return { to = to, why = "marker" } end
	return { to = to, why = "rendering" }
end

-- The live atmosphere fields (api type.d.tl Environment.AthmostphereParams; probe T6: all six live-settable).
-- A look switch resets them to the file's; the values from before the switch are put back.
P.LIVE = { "cloudCoverage", "cloudBase", "cloudTop", "cloudScattering", "dayOfYear", "sunRotation" }

--- The live fields of an atmosphere record (numbers only).
function P.liveOf(a)
	local out = {}
	if a == nil then return out end
	for __, k in ipairs(P.LIVE) do
		local ok, v = pcall(function() return a[k] end)
		if ok and finite(v) then out[k] = v end
	end
	return out
end

--- Writes `live` into atmosphere record `a`.
function P.applyLive(a, live)
	for __, k in ipairs(P.LIVE) do
		if live[k] ~= nil then a[k] = live[k] end
	end
end

---------------------------------------------------------------------------
-- Easing

--- Smoothstep on 0..1 (clamped): starts and ends at rest.
function P.smoothstep(u)
	u = clamp(u, 0, 1)
	return u * u * (3 - 2 * u)
end

--- Value between a and b at progress u (0..1) along curve "smooth" (default) or "linear".
function P.ease(a, b, u, curve)
	local w = curve == "linear" and clamp(u, 0, 1) or P.smoothstep(u)
	return a + (b - a) * w
end

---------------------------------------------------------------------------
-- Weather over time (pm_light fields cloud, cloudBase, cloudTop; the override restores them)

-- cloud is the TF3 scale 0..1 (game_time.script.tl: rainy weather mean 1.0, sunny 0.0; the wiki's 0..0.5 with
-- rain at 0.45 is TF2-era). Where rain starts is to be seen in game (LOOKS.md K6).
P.WEATHER = {
	-- clear to rain: starts from at most 0.1 (a clear sky; the click asks for the whole story)
	storm = { dur = 40, cloudStart = 0.1, cloud = 1.0 },
	-- rain to clear: starts from at least 0.9
	clearing = { dur = 40, cloudStart = 0.9, cloud = 0.0 },
	-- a low, thick deck: base 1500 m -> 500 m, top 3600 m -> 1800 m (base climates), at least 0.6 cover
	lowclouds = { dur = 8, cloudBase = 500, cloudTop = 1800, cloudMin = 0.6 },
}
P.WEATHER_ORDER = { "storm", "clearing", "lowclouds" }

--- The animation for weather `kind` from the current values `cur` (pm_light fields): { kind, dur, from, to }
--- with from / to holding the fields it moves; nil for an unknown kind.
function P.weatherPlan(kind, cur, dur)
	local w = P.WEATHER[kind]
	if w == nil then return nil end
	cur = cur or {}
	local from, to = {}, {}
	local c = finite(cur.cloud) and cur.cloud or 0
	if kind == "storm" then
		from.cloud, to.cloud = math.min(c, w.cloudStart), w.cloud
	elseif kind == "clearing" then
		from.cloud, to.cloud = math.max(c, w.cloudStart), w.cloud
	else
		from.cloud, to.cloud = c, math.max(c, w.cloudMin)
		from.cloudBase = finite(cur.cloudBase) and cur.cloudBase or 1500
		from.cloudTop = finite(cur.cloudTop) and cur.cloudTop or 3600
		to.cloudBase, to.cloudTop = w.cloudBase, w.cloudTop
	end
	return { kind = kind, dur = (finite(dur) and dur > 0) and dur or w.dur, from = from, to = to }
end

--- The values of animation `plan` `t` seconds after its start, and whether it is over.
function P.weatherAt(plan, t)
	local u = (finite(t) and plan.dur > 0) and t / plan.dur or 1
	local out = {}
	for k, a in pairs(plan.from) do out[k] = P.ease(a, plan.to[k], u) end
	return out, u >= 1
end

---------------------------------------------------------------------------
-- Time-lapse (time of day; GameTime Constant through the override)

local function declination(day)
	return math.rad(23.44) * math.sin(2 * math.pi * (284 + day) / 365)
end
P.declination = declination

--- The time of day (s) at which the sun stands `alt` radians up on day `day`, morning (pm false) or afternoon;
--- nil when it never gets there (the same model as pm_light.sunTime).
function P.sunTime(day, alt, pm, lat)
	local d = declination(day)
	local den = math.cos(lat) * math.cos(d)
	if math.abs(den) < 1e-9 then return nil end
	local cosH = (math.sin(alt) - math.sin(lat) * math.sin(d)) / den
	if cosH < -1 or cosH > 1 then return nil end
	local hours = math.deg(math.acos(cosH)) / 15
	return (pm and (12 + hours) or (12 - hours)) * 3600
end

-- sunrise: civil dawn (sun 6 degrees below) to the sun 12 degrees up; sunset: 14 degrees up (golden light) to
-- civil dusk; run: the clock at RATE game seconds per real second until stopped. Fallbacks: a day the sun never
-- reaches those heights (polar day / night).
P.RATE = 600 -- 10 game minutes per second: a day in 2.4 min
P.LAPSE = {
	sunrise = { fromAlt = -6, toAlt = 12, pm = false, dur = 45, fallback = { 5 * 3600, 8 * 3600 } },
	sunset = { fromAlt = 14, toAlt = -6, pm = true, dur = 45, fallback = { 18 * 3600, 21 * 3600 } },
	run = { rate = P.RATE },
}
P.LAPSE_ORDER = { "sunrise", "sunset", "run" }

--- The time-lapse plan: { kind, from, to, dur } (a sweep) or { kind, from, rate } (run); nil for an unknown kind.
function P.lapsePlan(kind, day, lat, curTime)
	local l = P.LAPSE[kind]
	if l == nil then return nil end
	if l.rate ~= nil then
		return { kind = kind, from = finite(curTime) and curTime or 12 * 3600, rate = l.rate }
	end
	day = finite(day) and day or 171
	lat = finite(lat) and lat or P.CLIMATES.temperate.lat
	local a = P.sunTime(day, math.rad(l.fromAlt), l.pm, lat)
	local b = P.sunTime(day, math.rad(l.toAlt), l.pm, lat)
	if a == nil or b == nil or b <= a then a, b = l.fallback[1], l.fallback[2] end
	return { kind = kind, from = a, to = b, dur = l.dur }
end

--- The time of day of `plan` `t` seconds after its start (not wrapped), and whether it is over.
function P.lapseAt(plan, t)
	t = (finite(t) and t > 0) and t or 0
	if plan.rate ~= nil then return plan.from + t * plan.rate, false end
	local u = t / plan.dur
	return P.ease(plan.from, plan.to, u, "linear"), u >= 1
end

---------------------------------------------------------------------------
-- Seasons (day of year; northern hemisphere: every base climate's latitude is north)

P.SEASONS = { winter = 355, spring = 80, summer = 172 } -- spring: the March equinox (round 12)
P.SEASON_ORDER = { "winter", "spring", "summer" }

---------------------------------------------------------------------------
-- Sun placement

--- The sun's altitude and azimuth (radians; azimuth from north, clockwise: east pi/2, south pi) on day `day` at
--- `t` seconds of the day, latitude `lat`. Textbook solar geometry with the clock as solar time (noon 12:00).
function P.solarPosition(day, t, lat)
	local d = declination(day)
	local h = (t / 3600 - 12) * math.rad(15)
	local sinAlt = math.sin(lat) * math.sin(d) + math.cos(lat) * math.cos(d) * math.cos(h)
	local alt = math.asin(clamp(sinAlt, -1, 1))
	local az = atan2(math.sin(h), math.cos(h) * math.sin(lat) - math.tan(d) * math.cos(lat)) + math.pi
	return alt, az % (2 * math.pi)
end

-- How the game's world and sunRotation relate to the compass (UNVERIFIED, LOOKS.md K10): north = the world
-- heading (math angle from +x towards +y) that points north (+y, the map's top, assumed); sign = +1 when a
-- positive sunRotation turns the sun counter-clockwise seen from above. In game, the world heading of the sun is
-- north - azimuth + sign * sunRotation. K10's two clicks tell which of the four (north, sign) pairs is right.
P.SUN_CAL = { north = math.pi / 2, sign = 1 }

-- Where the sun goes relative to the look heading: back(light) = in front of the camera (the subject against the
-- light), side = 90 degrees to the left (right on every second click), front = behind the camera.
P.SUN_PLACES = { back = 0, side = math.pi / 2, front = math.pi }
P.SUN_ORDER = { "back", "side", "front" }

--- The world heading of the sun for azimuth `az` and sunRotation `rot`.
function P.sunHeading(az, rot, cal)
	cal = cal or P.SUN_CAL
	return wrapAngle(cal.north - az + cal.sign * rot)
end

--- The sunRotation that puts the sun at `offset` from look heading `look` (both world headings), the sun's
--- azimuth being `az` at rotation 0.
function P.placeSun(offset, look, az, cal)
	cal = cal or P.SUN_CAL
	return wrapAngle(cal.sign * (look + offset - cal.north + az))
end

return P
